import{_ as o,c as i,o as a,ae as t}from"./chunks/framework.DMK_uHmU.js";const l="/help-center/assets/branding.DzfOydEJ.png",g=JSON.parse('{"title":"Platform Branding & Customization Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/global-settings/branding.md","filePath":"Administration/Manage/global-settings/branding.md"}'),r={name:"Administration/Manage/global-settings/branding.md"};function n(s,e,d,c,h,u){return a(),i("div",null,e[0]||(e[0]=[t('<h1 id="platform-branding-customization-guide" tabindex="-1">Platform Branding &amp; Customization Guide <a class="header-anchor" href="#platform-branding-customization-guide" aria-label="Permalink to &quot;Platform Branding &amp; Customization Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Platform Branding &amp; Customization tool allows administrators to personalize the visual appearance of the application to match organizational branding guidelines. This component provides comprehensive controls for customizing colors, uploading logos, and adjusting layout settings to create a cohesive branded experience.</p><h2 id="accessing-branding-settings" tabindex="-1">Accessing Branding Settings <a class="header-anchor" href="#accessing-branding-settings" aria-label="Permalink to &quot;Accessing Branding Settings&quot;">​</a></h2><p>The Branding Settings component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the tenant settings section and select &quot;Branding&quot; from the menu.</p><h2 id="organization-information" tabindex="-1">Organization Information <a class="header-anchor" href="#organization-information" aria-label="Permalink to &quot;Organization Information&quot;">​</a></h2><p>The top section of the branding page contains fields for essential organizational information:</p><p><img src="'+l+'" alt="homepage"></p><ol><li><p><strong>Company Name</strong> (Required)</p><ul><li>The official name of your organization</li><li>Displayed in various parts of the application</li><li>Required field that cannot be left empty</li></ul></li><li><p><strong>Company Alias</strong></p><ul><li>A shorter version or alternative name for your organization</li><li>Optional field used in space-constrained areas of the interface</li></ul></li><li><p><strong>Account Notes</strong></p><ul><li>Additional information about the account or branding guidelines</li><li>Optional field for administrative notes</li></ul></li></ol><h2 id="theme-customization" tabindex="-1">Theme Customization <a class="header-anchor" href="#theme-customization" aria-label="Permalink to &quot;Theme Customization&quot;">​</a></h2><p>The Colors &amp; Logo section provides comprehensive controls for adjusting the application&#39;s appearance.</p><h3 id="primary-colors" tabindex="-1">Primary Colors <a class="header-anchor" href="#primary-colors" aria-label="Permalink to &quot;Primary Colors&quot;">​</a></h3><p>The primary color is the main accent color used throughout the application for buttons, highlights, and interactive elements.</p><p>To set the primary color:</p><ol><li>Select one of the predefined color swatches, or</li><li>Use the custom color picker to select a precise color</li></ol><p>When a primary color is selected:</p><ul><li>The application automatically generates a color palette based on the selection</li><li>The theme updates in real-time to preview the changes</li><li>The &quot;custom&quot; theme is activated when using the color picker</li></ul><h3 id="secondary-colors" tabindex="-1">Secondary Colors <a class="header-anchor" href="#secondary-colors" aria-label="Permalink to &quot;Secondary Colors&quot;">​</a></h3><p>The secondary color is used for accents, highlights, and complementary elements.</p><p>To set the secondary color:</p><ol><li>Use the color picker to select a precise color</li><li>The application automatically generates a secondary color palette</li></ol><h3 id="surface-colors" tabindex="-1">Surface Colors <a class="header-anchor" href="#surface-colors" aria-label="Permalink to &quot;Surface Colors&quot;">​</a></h3><p>Surface colors control the background shades used throughout the application. There are separate controls for light and dark modes.</p><h4 id="light-mode-surface-color" tabindex="-1">Light Mode Surface Color <a class="header-anchor" href="#light-mode-surface-color" aria-label="Permalink to &quot;Light Mode Surface Color&quot;">​</a></h4><ol><li>Select from predefined surface color swatches</li><li>Changes affect background colors when in light mode</li></ol><h4 id="dark-mode-surface-color" tabindex="-1">Dark Mode Surface Color <a class="header-anchor" href="#dark-mode-surface-color" aria-label="Permalink to &quot;Dark Mode Surface Color&quot;">​</a></h4><ol><li>Select from predefined surface color swatches</li><li>Changes affect background colors when in dark mode</li></ol><h3 id="display-mode" tabindex="-1">Display Mode <a class="header-anchor" href="#display-mode" aria-label="Permalink to &quot;Display Mode&quot;">​</a></h3><p>Control whether the application uses light or dark mode by default:</p><ol><li>Select &quot;Light&quot; or &quot;Dark&quot; from the Display Mode toggle</li><li>The application instantly previews the selected mode</li><li>Users can still override this setting with their personal preferences</li></ol><h3 id="gradient-generator" tabindex="-1">Gradient Generator <a class="header-anchor" href="#gradient-generator" aria-label="Permalink to &quot;Gradient Generator&quot;">​</a></h3><p>Create custom gradients for use in promotional areas or backgrounds:</p><ol><li>Select colors for the gradient start, middle, and end points</li><li>Preview the gradient in real-time</li><li>The gradient is stored for use in compatible application areas</li></ol><h2 id="logo-management" tabindex="-1">Logo Management <a class="header-anchor" href="#logo-management" aria-label="Permalink to &quot;Logo Management&quot;">​</a></h2><p>The Manage Application Logos section allows you to upload and configure the logos used throughout the application.</p><h3 id="logo-types" tabindex="-1">Logo Types <a class="header-anchor" href="#logo-types" aria-label="Permalink to &quot;Logo Types&quot;">​</a></h3><p>The system requires four distinct logo files:</p><ol><li><p><strong>Logo Light</strong></p><ul><li>The primary full logo on light backgrounds</li><li>Recommended size: 155px × 60px</li><li>Used in headers and main navigation areas</li></ul></li><li><p><strong>Mark Light</strong></p><ul><li>The icon-only version on light backgrounds</li><li>Recommended size: 50px × 50px</li><li>Used in space-constrained areas and mobile views</li></ul></li><li><p><strong>Logo Dark</strong></p><ul><li>The primary full logo on dark backgrounds</li><li>Recommended size: 155px × 60px</li><li>Automatically used when dark mode is active</li></ul></li><li><p><strong>Mark Dark</strong></p><ul><li>The icon-only version on dark backgrounds</li><li>Recommended size: 50px × 50px</li><li>Used in space-constrained areas when dark mode is active</li></ul></li></ol><h3 id="uploading-logos" tabindex="-1">Uploading Logos <a class="header-anchor" href="#uploading-logos" aria-label="Permalink to &quot;Uploading Logos&quot;">​</a></h3><p>To update any logo:</p><ol><li>Click on the logo card you wish to update</li><li>The logo editor dialog will open showing the current logo</li><li>Click the folder icon or drag and drop a new image</li><li>Use the editor tools to crop and adjust the image</li><li>Click &quot;Save logo&quot; to apply changes</li></ol><h3 id="logo-editor" tabindex="-1">Logo Editor <a class="header-anchor" href="#logo-editor" aria-label="Permalink to &quot;Logo Editor&quot;">​</a></h3><p>The built-in logo editor provides several tools:</p><ol><li><strong>Open</strong>: Import an image from your device</li><li><strong>Crop</strong>: Adjust the visible portion of the image</li><li><strong>Confirm</strong>: Accept the current crop selection</li><li><strong>Reset</strong>: Revert to the original image</li><li><strong>Save logo</strong>: Finalize and upload the edited logo</li></ol><p>The editor automatically resizes images to the appropriate dimensions:</p><ul><li>Full logos to 155px × 60px</li><li>Mark logos to 50px × 50px</li></ul><h2 id="advanced-layout-settings" tabindex="-1">Advanced Layout Settings <a class="header-anchor" href="#advanced-layout-settings" aria-label="Permalink to &quot;Advanced Layout Settings&quot;">​</a></h2><p>For advanced users, additional controls are available to customize the application layout.</p><h3 id="menu-type" tabindex="-1">Menu Type <a class="header-anchor" href="#menu-type" aria-label="Permalink to &quot;Menu Type&quot;">​</a></h3><p>Select from different navigation menu styles:</p><ul><li><strong>Static</strong>: Fixed side menu that remains visible</li><li><strong>Overlay</strong>: Menu slides over content when activated</li><li><strong>Slim</strong>: Narrow icons-only menu that expands on hover</li><li><strong>Slim+</strong>: Enhanced slim menu with additional information</li><li><strong>Reveal</strong>: Menu that reveals when triggered</li><li><strong>Drawer</strong>: Slide-out panel containing the menu</li><li><strong>Horizontal</strong>: Menu that spans horizontally across the top</li></ul><h3 id="menu-theme" tabindex="-1">Menu Theme <a class="header-anchor" href="#menu-theme" aria-label="Permalink to &quot;Menu Theme&quot;">​</a></h3><p>Choose how the menu&#39;s appearance relates to the overall theme:</p><ul><li><strong>Color Scheme</strong>: Menu uses the application&#39;s color scheme</li><li><strong>Primary Color</strong>: Menu uses the primary color as its background</li><li><strong>Transparent</strong>: Menu has a transparent background</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For optimal branding results:</p><ol><li><p><strong>Logo Consistency</strong></p><ul><li>Maintain consistent visual elements between light and dark versions</li><li>Ensure all logos are clearly visible on their intended backgrounds</li><li>Use transparent backgrounds for logos when possible</li></ul></li><li><p><strong>Color Selection</strong></p><ul><li>Choose colors that reflect your brand identity</li><li>Ensure sufficient contrast for accessibility</li><li>Test your color scheme in both light and dark modes</li></ul></li><li><p><strong>Gradient Usage</strong></p><ul><li>Use gradients sparingly for maximum impact</li><li>Ensure gradient colors complement your primary brand colors</li><li>Test gradients for readability when text is overlaid</li></ul></li><li><p><strong>Regular Review</strong></p><ul><li>Periodically review how branding appears across different devices</li><li>Check that colors and logos remain consistent across the application</li><li>Update branding when organizational guidelines change</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Logo appears distorted after upload</p><ul><li>Use an image with the recommended dimensions</li><li>Ensure the image has sufficient resolution</li><li>Try using the crop tool to better fit the available space</li></ul><p><strong>Issue</strong>: Colors don&#39;t update immediately</p><ul><li>Toggle between light and dark mode to refresh the theme</li><li>Refresh the browser if changes aren&#39;t appearing</li><li>Check network connectivity for upload issues</li></ul><p><strong>Issue</strong>: Unable to upload logos</p><ul><li>Check that the image format is supported (PNG recommended)</li><li>Ensure file size is below the maximum limit</li><li>Verify you have the appropriate permissions</li></ul><p><strong>Issue</strong>: Gradient preview doesn&#39;t match actual appearance</p><ul><li>Different screens may display colors differently</li><li>Test on multiple devices if possible</li><li>Adjust colors for better cross-device consistency</li></ul><p><strong>Issue</strong>: Logo upload shows error</p><ul><li>Check the error message in the notification</li><li>Verify the image format and dimensions</li><li>Try a different browser if the issue persists</li></ul><hr><p>For additional assistance with branding customization, please contact your system administrator.</p>',72)]))}const m=o(r,[["render",n]]);export{g as __pageData,m as default};
